#!/usr/bin/env bash
#
# Packages the files generated by `haskellBook --epub` into an EPUB 3 file.
# The container follows the layout used by Standard Ebooks (https://github.com/standardebooks/tools):
#
#   mimetype
#   META-INF/container.xml
#   epub/content.opf
#   epub/toc.xhtml
#   epub/css/style.css
#   epub/images/*.svg
#   epub/text/*.xhtml
#
# The resulting file is validated if epubcheck is installed.

set -euo pipefail

if [ $# -ne 3 ]; then
    echo "Usage: $0 XHTML_DIR IMG_DIR OUTPUT_FILE" >&2
    exit 1
fi

xhtml_dir=$1
img_dir=$2
output=$(realpath -m "$3")
stylesheet="$(dirname "$(realpath "$0")")/book/epub/style.css"

build_dir=$(mktemp -d)
trap 'rm -rf "$build_dir"' EXIT

mkdir -p "$build_dir/META-INF" "$build_dir/epub/css" "$build_dir/epub/images" "$build_dir/epub/text"

printf "application/epub+zip" > "$build_dir/mimetype"

cat > "$build_dir/META-INF/container.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<container xmlns="urn:oasis:names:tc:opendocument:xmlns:container" version="1.0">
	<rootfiles>
		<rootfile full-path="epub/content.opf" media-type="application/oebps-package+xml"/>
	</rootfiles>
</container>
EOF

cp "$xhtml_dir/content.opf" "$xhtml_dir/toc.xhtml" "$build_dir/epub/"
for file in "$xhtml_dir"/*.xhtml; do
    if [ "$(basename "$file")" != "toc.xhtml" ]; then
        cp "$file" "$build_dir/epub/text/"
    fi
done
cp "$stylesheet" "$build_dir/epub/css/style.css"

# Every file in the container has to be declared in the manifest, so unused illustrations are left out
sed -n 's|.*href="images/\([^"]*\)".*|\1|p' "$build_dir/epub/content.opf" | while read -r image; do
    cp "$img_dir/$image" "$build_dir/epub/images/"
done

rm -f "$output"
cd "$build_dir"
# The mimetype file has to be the first, uncompressed entry of the archive
zip -X0q "$output" mimetype
zip -X9qr "$output" META-INF epub
echo "Saved $output"

if command -v epubcheck > /dev/null; then
    epubcheck "$output"
else
    echo "epubcheck is not installed, skipping validation"
fi
